import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.BZO4qERu.js";const m=JSON.parse('{"title":"Models and ranking","description":"","frontmatter":{},"headers":[],"relativePath":"guide/models.md","filePath":"guide/models.md","lastUpdated":1792570296000}'),r={name:"guide/models.md"};function i(s,e,d,l,c,h){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="models-and-ranking" tabindex="-1">Models and ranking <a class="header-anchor" href="#models-and-ranking" aria-label="Permalink to &quot;Models and ranking&quot;">​</a></h1><p>Use a language model for search planning and relevance assessment. Optional preliminary ranking helps choose the candidates for final model scoring.</p><h2 id="connect-a-model" tabindex="-1">Connect a model <a class="header-anchor" href="#connect-a-model" aria-label="Permalink to &quot;Connect a model&quot;">​</a></h2><p>In Community, or online with your own key, open <strong>Settings → Model APIs → Add connection</strong>. Choose the connection type, provider, and model, then verify the key, base URL, and protocol. Presets are starting values; the provider must offer that model.</p><p><strong>Test connection</strong> in the model dialog checks the current draft without saving it. Click <strong>Save</strong> to create or update the connection, then select it for search or writing. Data-source dialog tests behave differently: they save before testing; see <a href="./sources">data sources</a>.</p><table tabindex="0"><thead><tr><th>Protocol</th><th>Operation</th></tr></thead><tbody><tr><td>OpenAI Chat Completions</td><td><code>/chat/completions</code></td></tr><tr><td>OpenAI Responses</td><td><code>/responses</code></td></tr><tr><td>Anthropic Messages</td><td><code>/v1/messages</code></td></tr></tbody></table><p>Use the base URL expected by the protocol, without duplicating the operation path. Chat Completions compatibility does not imply Responses compatibility.</p><p>PaperSeek Service provides a model dropdown; PaperSeek manages the endpoints and keys.</p><h2 id="preliminary-ranking" tabindex="-1">Preliminary ranking <a class="header-anchor" href="#preliminary-ranking" aria-label="Permalink to &quot;Preliminary ranking&quot;">​</a></h2><p><strong>Local fusion is the default.</strong></p><table tabindex="0"><thead><tr><th>Mode</th><th>Behavior</th><th>Extra service</th></tr></thead><tbody><tr><td>Local fusion</td><td>Combines local lexical/hashed semantic signals and retrieval ranks</td><td>None</td></tr><tr><td>Embedding + Rerank</td><td>External embedding and reranking before final selection</td><td>Embedding and reranking APIs</td></tr><tr><td>Decision model</td><td>Scores locally fused candidates with the System One protocol</td><td>Compatible decision API</td></tr></tbody></table><p>Local fusion refers only to preliminary ranking. The complete search still uses a language model and network requests.</p><p>The decision route assesses up to twice the final LLM candidate budget before choosing the final subset. Available candidates and budget limits still apply.</p><h2 id="settings-by-edition" tabindex="-1">Settings by edition <a class="header-anchor" href="#settings-by-edition" aria-label="Permalink to &quot;Settings by edition&quot;">​</a></h2><p><strong>Community / your own key:</strong> configure model routes and credentials. The writing model can differ from the search model.</p><p><strong>PaperSeek Service:</strong> search uses Auto; review writing uses Fast or Deep Research. Preliminary-ranking choices remain visible, while endpoints and secrets stay on the server.</p><h2 id="local-models" tabindex="-1">Local models <a class="header-anchor" href="#local-models" aria-label="Permalink to &quot;Local models&quot;">​</a></h2><p>Community can connect to a compatible model reachable from the machine running PaperSeek, including loopback.</p><p>Online, connections saved with your own key cannot point to loopback, private, link-local, or other unsafe destinations, which protects the server against SSRF. <code>127.0.0.1</code> would address the online server, not your laptop. Use Community for local endpoints.</p><h2 id="fallbacks-and-failures" tabindex="-1">Fallbacks and failures <a class="header-anchor" href="#fallbacks-and-failures" aria-label="Permalink to &quot;Fallbacks and failures&quot;">​</a></h2><p>An optional ranking failure can preserve local ordering with a warning; it does not mean external ranking succeeded. Check the recorded run configuration and execution status.</p><p>Authentication, credit, rate-limit, timeout, and invalid-response errors require different remedies. See <a href="./../reference/troubleshooting">troubleshooting</a>.</p>',22)])])}const u=t(r,[["render",i]]);export{m as __pageData,u as default};
